ALREADY={'goodwill','multiyear'}
def rootwords(i):return list(dict.fromkeys(w for w in ASSIGN['roots'][i]['family'] if w not in DEFERRED and '-' not in w))
def rootexclude(i):
 r=ASSIGN['roots'][i];c=CATALOG[r['id']];return {w:DEFERRED[w] for w in set(r['family'])|set(c['family'])|set(c['words'])|set(c['unmatched']) if w in DEFERRED}
def checkpoint(note):
 Path('.cache/batch200/st62-working-words.json').write_text(json.dumps(W,ensure_ascii=False,indent=2)+'\n')
 p=Path('.cache/batch200/rewrite_st_progress.json');d=json.loads(p.read_text());d.update(active_batch='st62',active_script='scripts/author_batch200_st_62.py',active_written_words=len(W),active_note=note);p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
def stage():
 index={}
 for f in glob.glob('content/精讲/words_*.json')+glob.glob('.cache/batch200/drafts/*/words_*.json'):
  if Path(f).name in {'words_batch200_integrated.json','words_batch200_st_62.json'}:continue
  data=json.loads(Path(f).read_text())
  for row in (data.values() if isinstance(data,dict) else data):
   if isinstance(row,dict) and row.get('word'):index.setdefault(row['word'],[]).append(f)
 assert len(W)==len({x['word'] for x in W})
 assert not {x['word']:index[x['word']] for x in W if x['word'] in index}
 for x in W:
  assert all(x.get(k) for k in ['ipa','meaning','sense','split','history','explanation','usage','contrast','sources'])
  assert len(x['examples'])>=2 and all(len(e)==2 and all(e) for e in x['examples'])
  assert len(x['history'])>=2 and all(len(h)==2 and all(h) for h in x['history'])
 for r in roots:
  c=CATALOG[r['id']];original={w for w in set(c['family'])|set(c['words'])|set(c['unmatched']) if '-' not in w}
  assert original<=set(r['words'])|set(r['exclude']),(r['id'],original-set(r['words'])-set(r['exclude']))
  assert all(w in index or w in {x['word'] for x in W} for w in r['words']),(r['id'],'unclosed reference')
 for kind,data in [('roots',roots),('words',W)]: (OUT/f'{kind}_batch200_st_62.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
W += [
E('good','/ɡʊd/','好的；合适的；有益的；善良的；好处','不是所有场景都在打同一张优秀分数表：好工具要管用，好朋友要可靠，好建议要适合当前事情。','古英语 gōd 接日耳曼好、合适词族，经中古英语进入现代 good。与 God 上帝不是同一个词；better、best 虽担当比较形式，也不由 good 的字母变出来。',GOOD,'good at maths 说擅长，good for you 说有益，good to someone 说待人友善。do some good 是产生好处；for good 是永久，不是为了做好事。','good at；good for；good to；do good；for good。','good 多作形容词，well 常修饰动作：a good writer、writes well。feel good 说感觉不错，feel well 常更关注身体健康。',('This is a good tool for opening tight lids.','这是打开拧得很紧的盖子的好工具。'),('A short break might do us some good.','短暂休息一下也许对我们有好处。'),('She is good at making complicated ideas clear.','她擅长把复杂的想法解释清楚。'),sources=[OX('good_1'),OX('good_2'),ET('goodness'),'https://en.wiktionary.org/wiki/good#English']),
E('goodness','/ˈɡʊdnəs/','善良；好品质；有益成分；天哪〔感叹〕','把一个人的好心，或一种东西对人有益的部分，单独拿出来命名。','古英语已有 gōdnes，现代可认 good + -ness；它不是近代才给 good 添尾巴。感叹句中的 goodness 后来成为较温和的强调说法。',[['古英语 gōd 好；-nes 性质名词材料','组合为好、善的性质'],['古英语 gōdnes → 中古英语 → goodness','善良、好处；后来也用于感叹']],'the goodness of her heart 是她内心的善意；the goodness in food 可说食物中有益的营养。My goodness! 表示惊讶，Thank goodness! 表示谢天谢地。','out of the goodness of one’s heart；natural goodness；my goodness；thank goodness。','kindness 更具体说待人的善意，goodness 范围还包括品质、有益成分和感叹用法；不能每次都译为道德高尚。',('He helped out of the goodness of his heart.','他帮忙完全是出于一片好心。'),('Thank goodness we checked the address before leaving.','谢天谢地，我们出发前核对了地址。'),sources=[OX('goodness'),ET('goodness')]),
E('goods','/ɡʊdz/','商品；货物；个人物品、财物','能够拥有、搬运、出售的一批东西，后来尤其常指进入交易的货品。','good 在古英语里就可作财物、好东西等名词；复数 goods 后来常用于财产，再发展出商品、货物义。不是在现代形容词好的后面加 s 表示很多好。',[['古英语名词 gōd 好处、财物；复数用法','从值得拥有的东西到财物'],['中古英语 goods → 现代 goods','财产、物品；尤其指可出售或运输的商品']],'damaged goods 是受损货物，household goods 是家居用品。这个词通常按复数处理：The goods are ready；经济学中单数 a good 可指一种商品。','consumer goods；household goods；deliver goods；goods and services。','goods 是物品，goodness 是性质。日常买一件商品通常说 an item 或 a product，不机械使用 a goods。',('The goods are ready for collection at the warehouse.','货物已备好，可以到仓库提取。'),('The shop sells household goods made by local craftspeople.','这家店出售当地手艺人制作的家居用品。'),sources=[OX('goods'),ET('goods')]),
E('goodbye','/ˌɡʊdˈbaɪ/','再见；告别','原先是一句离别祝愿，长期连读后缩成了今天普通的告别词。','来自 God be with you 愿上帝与你同在的缩合，早期有 Godby 等形式；受 good morning、good night 等影响，开头改成 good。不是一开始就由好 + bye 独立组成。',[['God be with you／ye 的离别祝愿','整句说得简短，出现 Godby、God b’w’y 等形式'],['缩合词受 good morning／good night 影响 → goodbye','形式改成 good 开头，现代成为普通告别语']],'say goodbye to someone 是向某人告别；a sad goodbye 是一次难过的告别。现代日常说 goodbye 并不要求说话者在表达宗教信仰。','say goodbye；wave goodbye；a final goodbye；kiss something goodbye〔放弃指望〕。','good 与 God 本来不同源；这个词中是短语缩合再受相似问候影响。bye 是常用短形式。',('We waved goodbye as the train pulled out.','火车驶出时，我们挥手告别。'),('The letter gave her a chance to say a proper goodbye.','那封信让她有机会好好道别。'),sources=[OX('goodbye_1'),OX('goodbye_2'),MW('good-bye')]),
E('goodnight','/ˌɡʊdˈnaɪt/','晚安；夜间道别的话〔也写 good night〕','一天快结束，或准备分开去睡觉时，祝对方接下来过一个好夜晚。','good 好 + night 夜晚，形成祝愿式告别语；可分写 good night，也见合写 goodnight。与 goodbye 的整句缩合来源不同。',[['英语 good 好；night 夜晚','两个材料共同表达夜晚祝愿'],['good night → 也合写 goodnight','晚间道别、睡前问候；可名词化为一次晚安']],'say goodnight to the children 是向孩子道晚安。通常用于晚上告别或就寝前，不是刚在晚会碰面就一律用它打招呼。','say goodnight；a goodnight kiss；goodnight, everyone。','good evening 常用于晚上见面问候；goodnight 更常用于离开或结束这一天。区别不只是钟表上几点。',('She said goodnight to the children and turned off the hallway light.','她向孩子们道了晚安，关掉了走廊的灯。'),('Goodnight, everyone. I will see you in the morning.','大家晚安，我们早上见。'),sources=[OX('goodnight'),'https://en.wiktionary.org/wiki/goodnight#English']),
E('goody','/ˈɡʊdi/','好吃的东西、小礼物；太好了〔口语〕','把好东西叫得亲切一点：吃的小点心、领到的小礼物，或孩子式的一声欢呼。','good + -y 的亲切、口语形式；好吃的东西义后来也扩展到礼物等，感叹用法表示开心。历史称呼 Goody 另可由 goodwife 缩短，别与普通小礼物义混成一条派生线。',[['英语 good 好；口语名词后缀 -y','形成令人喜欢的好东西称呼'],['英语 goody／goodie；另有感叹 Goody!','食物、礼物等；表达高兴的欢呼']],'a bag of goodies 常是一袋小礼物或零食，复数拼 goodies。单独说 Goody! 有孩子气，也可能被成年人故意拿来反讽。','a bag of goodies；sweet goodies；Goody!；goody bag。','goodie 是常见的同义拼法；good 只是好的，goody 通常指一个好东西或表示欢呼，不是正式褒奖用语。',('The table was covered with homemade goodies.','桌上摆满了自制的好吃的小点心。'),('Goody! We have time for one more game.','太好了！我们还有时间再玩一局。'),sources=[OX('goody_1'),OX('goody_2'),ET('goody')]),
E('goodie','/ˈɡʊdi/','好吃的小东西；小礼物；故事里的好人〔口语〕','可以是一袋让人高兴的小赠品，也可以是故事中被当作好人阵营的角色。','good + -ie，是 goody 的常见拼法；直接材料仍是好的与亲切称呼词尾。人物用法把好人当作一个角色标签。',[['英语 good 好；口语后缀 -ie／-y','与 goody 属于同一组形式'],['英语 goodie','好东西、小礼物；也指故事中的好人']],'goodie bags 是活动发的小礼品袋；the goodies and the baddies 是故事里的好人和坏人。具体译法看讲的是礼物还是人物。','a goodie bag；free goodies；the goodies and the baddies。','它不是另一个独立古词根，与 goody 在主要名词义上是拼写变体；goodies 不必都是食物。',('Each visitor received a goodie bag with a notebook and a pencil.','每位来访者都领到一个装有笔记本和铅笔的小礼品袋。'),('The film makes it hard to tell the goodies from the baddies.','这部电影让人很难分清谁是好人、谁是坏人。'),sources=[OX('goodie'),ET('goody'),'https://en.wiktionary.org/wiki/goodie#English']),
E('better','英 /ˈbetə/；美 /ˈbetər/','更好的；更好地；改善；超过','拿两个状态相比，向更合适、更有效或更舒服的那一边移动。','古英语 betera 等比较形式和 beterian 改善动词延续到现代；与 good 是语法上的配套，而不是 good 加 -er。better 同时也担当 well 的比较形式。',BETTER,'a better idea 是更好的想法，work better 是运作得更好；feel better 可说状态改善。动词 better yourself 指改善自身处境，better a record 指超过纪录。','better than；feel better；better results；better yourself；had better do…。','better 不等于绝对最好，只表示比某个对象或状态好。had better 接原形，常带建议甚至警告，不是普通过去时。',('The new layout works better on a small screen.','新布局在小屏幕上效果更好。'),('She moved to the city to better her prospects.','她搬到城市，希望改善自己的发展前景。'),sources=[OX('better_1'),OX('better_2'),OX('better_3'),MW('better')]),
E('best','/best/','最好的；最好地；最大努力；胜过〔动词〕','把正在比较的一组放在一起，挑出最符合当前标准的那个。','古英语 betest、betst 等最高级形式，接与 better 相关的词族；不是 good + -est。它早已与 good、well 配套，后来又有名词和动词用法。',[['古英语 betest／betst 等最高级形式','与 better 同属比较词族，而不是 good 的加尾形式'],['英语 best','最好的、最好地；名词最强表现，后来也可作胜过的动词']],'the best option 要有比较范围；do your best 是尽最大努力。best a rival 是击败对手，属于较书面用法。best wishes 则是祝愿语，不是在给祝福排名。','the best choice；do your best；at best；a personal best；best wishes。','better 只要求更好，best 在所谈范围中最高；at best 常说至多、充其量，与 at your best 状态最佳不同。',('This is the best route if we want to avoid traffic.','如果想避开拥堵，这就是最好的路线。'),('She did her best even though the equipment was unfamiliar.','虽然不熟悉设备，她还是尽了最大努力。'),sources=[OX('best_1'),OX('best_2'),MW('best')]),
E('betterment','英 /ˈbetəmənt/；美 /ˈbetərmənt/','改善；改进；境遇提升〔正式〕','不是只评一句更好了，而是把让生活、条件或制度变好的过程作为目标。','better 改善这个动词 + -ment，十六世纪已有名词。直接来源是动词一支，不是给 good 生硬加一长串后缀。',BETTER+[['英语动词 better + -ment → betterment','把改善的过程或结果名词化']],'for the betterment of the community 是为了改善社区整体状况。这个词常见于公共事务、教育或较正式的愿景表述，日常改个按钮往往用 improvement 更自然。','social betterment；the betterment of society；for the betterment of…。','improvement 更通用；betterment 较强调境遇、条件或整体福祉向好，不是 better 的最高级。',('The project aims at the betterment of living conditions in the neighbourhood.','这个项目旨在改善社区的居住条件。'),('She devoted much of her time to the betterment of local education.','她把许多时间用于改善当地教育。'),sources=[OX('betterment'),ET('betterment')]),
]
GOOD_ROOT=dict(id='B2680',meaning='好；合适、有益、值得肯定',core='好不是一种固定物质，而是某个人或东西符合眼前需要、标准或价值判断。',image='古英语 gōd → good；gōdnes → goodness；名词财物复数 → goods；good + night → goodnight。另有 God be with you 缩合、受 good 问候影响 → goodbye；比较搭配另源 better／best。',intro='先用 good at、good for、good to 分清擅长、有益和待人友善。goods 是财物、商品，goodness 是好品质。better、best 与 good 配套但不由它派生；goodbye 则保存短语缩合和后来改写的历史。',forms='good 读 /ɡʊd/，不是 /ɡuːd/；goods 末尾读 /dz/。goodie、goody 的常见名词义是变体，复数都写 goodies。goodnight 常与分写 good night 并存。',branches=[['品质、善意与财物','good, goodness, goods, goodwill'],['日常告别和晚安','goodbye, goodnight'],['口语里的好东西','goody, goodie'],['比较系统的另源配套','better, best, betterment']],contrasts='good 与 God 不是同根；goodbye 的拼写却确实受到 good 系列问候影响。better/best 是语法上的同组，不可伪造 good 到 better 的字母演化。',practice='各用 good at、good for、good to 造句，再比较 goods 与 goodness；最后解释 goodbye 为什么不能简单译成好加再见。',words=list(dict.fromkeys(rootwords(312)+['goodwill'])),exclude=rootexclude(312))
